{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Practical coaching to build lasting habits and calm. Programs, frameworks, and a free guide to get you started." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="main-nav">
        <a href="about.html">About</a>
        <a href="programs.html">Paths</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html" class="primary">Start</a>
        <a href="contact.html">Connect</a>
      </nav>
      <button class="nav-toggle" id="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1>Gentle structure, bolder results</h1>
          <p class="lead">With {{COACH_NAME}}, {{CREDENTIALS}}, build routines that actually stick — a practical roadmap for energy, sleep, and daily calm. No fad promises, just steady progress.</p>
          <div class="hero-ctas">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn btn-ghost" href="book.html">Book a quick call</a>
          </div>
          <ul class="hero-stats">
            <li><strong>4</strong> proven steps</li>
            <li><strong>30+</strong> frameworks</li>
            <li><strong>Free</strong> starter guide</li>
          </ul>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="Graphic representing balance and motion" />
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof">
      <div class="container">
        <p class="eyebrow">Trusted by individuals in {{CITY}}, {{STATE}}</p>
        <div class="test-logos">
          <div class="logo">A</div>
          <div class="logo">B</div>
          <div class="logo">C</div>
          <div class="logo">D</div>
        </div>
        <div class="testimonials">
          <blockquote>"I finally sleep through the night and still have energy at 4pm — small, steady changes that actually work." <cite>— Alex, client</cite></blockquote>
          <blockquote>"{{COACH_NAME}} helped me build a simple daily rhythm that's sustainable. My mood and focus improved." <cite>— Morgan, client</cite></blockquote>
        </div>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits">
      <div class="container">
        <h2>What you'll gain</h2>
        <div class="benefit-grid">
          <article>
            <h3>Consistent energy</h3>
            <p>Practical morning and evening anchors so you stop swinging between highs and lows.</p>
          </article>
          <article>
            <h3>Habits that last</h3>
            <p>Micro-habits and environmental tweaks that make new behaviors automatic.</p>
          </article>
          <article>
            <h3>Clearer focus</h3>
            <p>Rituals to reduce friction and protect productive blocks without burnout.</p>
          </article>
          <article>
            <h3>Confident decisions</h3>
            <p>Tools to choose the right next step instead of cycling through options.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process">
      <div class="container">
        <h2>Our four-step rhythm</h2>
        <ol class="process-steps">
          <li>
            <strong>1. Map</strong>
            <p>We chart your current days and pain points with non-judgmental listening.</p>
          </li>
          <li>
            <strong>2. Design</strong>
            <p>Create tiny experiments tailored to your calendar and preferences.</p>
          </li>
          <li>
            <strong>3. Practice</strong>
            <p>Short accountability loops and habit scaffolds — measurable, bite-sized progress.</p>
          </li>
          <li>
            <strong>4. Embed</strong>
            <p>Turn what works into a reliable system you can maintain independently.</p>
          </li>
        </ol>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet">
      <div class="container lead-grid">
        <div class="lead-copy">
          <h2>Free guide: 7 Tiny Practices for a Calmer Week</h2>
          <p>Download a short, practical guide that helps you reset your next seven days. Simple steps, no fluff.</p>
          <form id="lead-form" class="lead-form" action="#" method="post">
            <label for="lead-name">Your name</label>
            <input id="lead-name" name="name" type="text" placeholder="Your name" required />
            <label for="lead-email">Email</label>
            <input id="lead-email" name="email" type="email" placeholder="you@domain.com" required />
            <button class="btn btn-primary" type="submit">Send the guide</button>
          </form>
          <p class="privacy">We respect your privacy. Your info is used only to send the guide and occasional tips.</p>
        </div>
        <div class="lead-art">
          <img src="assets/img/avatar.svg" alt="Avatar of {{COACH_NAME}}" />
          <p class="coach-sign">Coaching by <strong>{{COACH_NAME}}, {{CREDENTIALS}}</strong></p>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq">
      <div class="container">
        <h2>Common questions</h2>
        <div class="faq-list">
          <details>
            <summary>How long before I notice change?</summary>
            <p>Most clients report small shifts within 1–3 weeks; sustained patterns develop over several months depending on practice and consistency.</p>
          </details>
          <details>
            <summary>Is this therapy or medical care?</summary>
            <p>This is coaching focused on routines and behavior. It is not a substitute for medical or psychiatric care.</p>
          </details>
          <details>
            <summary>Do you offer short-term or ongoing plans?</summary>
            <p>Both. There are focused 4-week sprints and ongoing monthly partnerships depending on goals and support needs.</p>
          </details>
        </div>
      </div>
    </section>

    <!-- FINAL CTA -->
    <section class="final-cta">
      <div class="container final-grid">
        <div>
          <h2>Ready to build a calmer rhythm?</h2>
          <p>Book a no-pressure discovery session and see if the approach fits your life.</p>
        </div>
        <div class="cta-actions">
          <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn btn-ghost" href="book.html">Schedule a chat</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <div>
        <p>Contact</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <p>Navigate</p>
        <p><a href="about.html">About</a> · <a href="programs.html">Paths</a> · <a href="contact.html">Connect</a></p>
      </div>
    </div>
    <div class="container credit">© <span id="year"></span> {{BUSINESS_NAME}} • All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
