{"path":"assets/css/styles.css","content":"/* Bold playful theme — compact stylesheet */
:root{
  --bg:#fff;
  --muted:#6b7280;
  --accent:#ff6b6b;
  --accent-2:#6b8cff;
  --card:#f8fafc;
  --radius:12px;
  --max-width:1100px;
  --mono:ui-monospace,monospace;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:#0f172a; background:linear-gradient(180deg,#fff 0%, #fbfdff 100%)}
.container{max-width:var(--max-width);margin:0 auto;padding:24px}
.header-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none;font-size:1.1rem}
.nav{display:flex;gap:14px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.primary{background:var(--accent);color:#fff;padding:8px 12px}
.nav-toggle{display:none;border:0;background:transparent;font-size:1.4rem}

.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.hero-copy h1{font-size:2.1rem;margin:0;color:#0b1220}
.lead{color:var(--muted);margin:12px 0 18px}
.hero-ctas{display:flex;gap:12px;margin-bottom:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn-primary{background:linear-gradient(90deg,var(--accent),#ff8a8a);color:#fff}
.btn-ghost{background:transparent;border:2px solid #eef2ff;color:var(--accent-2)}
.hero-stats{display:flex;gap:18px;list-style:none;padding:0;margin:18px 0 0;color:var(--muted)}
.hero-art img{width:100%;max-width:420px;border-radius:14px}

.social-proof{padding:26px 0;background:linear-gradient(180deg,#fff,#fbfbff)}
.social-proof .eyebrow{color:var(--accent-2);font-weight:700}
.test-logos{display:flex;gap:12px;margin:14px 0}
.logo{width:72px;height:44px;background:#fff;border-radius:10px;display:flex;align-items:center;justify-content:center;color:var(--muted);font-weight:700;border:1px solid #f0f4ff}
.testimonials{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
blockquote{background:var(--card);padding:14px;border-radius:10px;margin:0;color:var(--muted)}
blockquote cite{display:block;margin-top:8px;color:#374151;font-style:normal;font-weight:600}

.benefits{padding:44px 0}
.benefit-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.benefit-grid article{background:#fff;padding:18px;border-radius:12px;border:1px solid #f3f4f6}
.benefit-grid h3{margin:0 0 8px;color:var(--accent-2)}

.process{padding:40px 0;background:linear-gradient(180deg,#fff,#fbfcff)}
.process-steps{display:flex;gap:14px;padding:0;list-style:none}
.process-steps li{background:#fff;padding:16px;border-radius:12px;border:1px solid #eef2ff;flex:1}
.process-steps strong{display:block;margin-bottom:8px;color:var(--accent)}

.lead-magnet{padding:44px 0}
.lead-grid{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:center}
.lead-form{display:flex;flex-direction:column;gap:8px;max-width:420px}
.lead-form input{padding:10px;border-radius:10px;border:1px solid #e6eefb}
.lead-art img{width:160px;border-radius:16px;border:6px solid #fff;box-shadow:0 6px 30px rgba(107,139,255,0.08)}
.coach-sign{margin-top:10px;color:var(--muted)}
.privacy{font-size:0.85rem;color:#9aa4b2}

.faq{padding:40px 0}
.faq-list details{background:#fff;padding:12px;border-radius:10px;border:1px solid #eef2ff;margin-bottom:8px}
.faq-list summary{font-weight:700;cursor:pointer}

.final-cta{padding:36px 0;background:linear-gradient(90deg,#fff,#fffaf3)}
.final-grid{display:flex;align-items:center;justify-content:space-between;gap:20px}
.cta-actions{display:flex;gap:12px}

.site-footer{border-top:1px solid #eef2ff;padding:24px 0;margin-top:32px;background:linear-gradient(180deg,#fbfbff,#fff)}
.footer-grid{display:flex;justify-content:space-between;gap:20px}
.credit{font-size:0.9rem;color:var(--muted);padding-top:14px}

/* Responsive */
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .lead-grid{grid-template-columns:1fr}
  .benefit-grid{grid-template-columns:repeat(2,1fr)}
  .process-steps{flex-direction:column}
  .nav{display:none}
  .nav-toggle{display:block}
}
@media(max-width:520px){
  .benefit-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactivity for navigation, lead form, and FAQ
document.addEventListener('DOMContentLoaded',function(){
  // year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // mobile nav toggle
  var btn=document.getElementById('nav-toggle');
  var nav=document.getElementById('main-nav');
  if(btn&&nav){
    btn.addEventListener('click',function(){
      nav.classList.toggle('open');
      if(nav.classList.contains('open')){nav.style.display='flex';nav.style.flexDirection='column';nav.style.background='#fff';nav.style.position='absolute';nav.style.right='24px';nav.style.top='64px';nav.style.padding='12px';nav.style.boxShadow='0 8px 30px rgba(11,18,32,0.08)'}
      else{nav.style.display='none'}
    });
  }

  // lead form submit
  var form=document.getElementById('lead-form');
  if(form){
    form.addEventListener('submit',function(e){
      e.preventDefault();
      var name=form.querySelector('input[name="name"]').value.trim();
      var email=form.querySelector('input[name="email"]').value.trim();
      if(!email){alert('Please enter your email.'); return}
      // Emulate sending
      var btn=form.querySelector('button');
      var old=btn.textContent; btn.textContent='Sending...'; btn.disabled=true;
      setTimeout(function(){
        btn.textContent='Sent';
        form.reset();
        setTimeout(function(){btn.textContent=old; btn.disabled=false},1800);
        alert('Thanks '+(name||'there')+"! We'll send your guide to " + email + '.');
      },900);
    });
  }

  // accessible details polyfill (basic)
  document.querySelectorAll('.faq-list details').forEach(function(d){
    d.addEventListener('toggle',function(){
      if(d.open) d.scrollIntoView({behavior:'smooth',block:'center'});
    });
  });
});"} 
